from __future__ import annotations

from typing import TYPE_CHECKING

from pydantic_ai import Agent
from pydantic_ai.messages import ModelMessage, ModelRequest, ModelResponse, TextPart, UserPromptPart

from ds.util.const import DEFAULT_AI_MODEL

if TYPE_CHECKING:
    from pydantic import BaseModel

__all__ = ["chat"]


# TODO: see if need this function or re-write so uses pydantic-ai
# original was purely to wrap over AI in single interface and ensure output was pydantic model
def chat(
    messages: list[dict], model: str = DEFAULT_AI_MODEL, response_format: type[BaseModel] | None = None
) -> BaseModel | str:
    """
    Send a chat message to the specified model and return the response.

    Args:
        messages (list[dict]): A list of messages in the format
            [{"role": "user", "content": "Hello"}]. "system" messages become the instructions,
            and the last message must be the "user" prompt.
        model (str): pydantic-ai model name. Default is DEFAULT_AI_MODEL (via AI Gateway).
        response_format (type[BaseModel] | None): If provided, the response will be validated
            against this Pydantic model.

    Returns
    -------
        BaseModel | str: The response from the model, either as a Pydantic model or plain text.
    """
    *earlier, last = messages
    if last["role"] != "user":
        msg = f"last message must be a 'user' prompt, got {last['role']!r}"
        raise ValueError(msg)
    instructions = "\n\n".join(m["content"] for m in messages if m["role"] == "system") or None
    # prior user/assistant turns (eg few-shot examples) carried over as conversation history
    history: list[ModelMessage] = []
    for m in earlier:
        if m["role"] == "user":
            history.append(ModelRequest(parts=[UserPromptPart(content=m["content"])]))
        elif m["role"] == "assistant":
            history.append(ModelResponse(parts=[TextPart(content=m["content"])]))
    agent = Agent(model, name="chat", instructions=instructions, output_type=response_format or str)
    return agent.run_sync(last["content"], message_history=history or None).output
